package com.sakib.portebo.ui.adapter;
import android.content.Context;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.LinearLayout;import android.widget.TextView;import android.widget.Toast;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.google.android.material.button.MaterialButton;import com.google.android.material.card.MaterialCardView;import com.sakib.portebo.R;import com.sakib.portebo.message.MessageManager;import com.sakib.portebo.ui.ThemePaletteManager;import java.text.SimpleDateFormat;import java.util.Date;import java.util.List;import java.util.Locale;
public class InboxAdapter extends RecyclerView.Adapter<InboxAdapter.Holder>{private final Context c;private final List<MessageManager.MessageItem> items;private final String token;public InboxAdapter(Context c,List<MessageManager.MessageItem> l,String t){this.c=c;items=l;token=t;}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){MaterialCardView card=new MaterialCardView(c);RecyclerView.LayoutParams cp=new RecyclerView.LayoutParams(-1,-2);cp.setMargins(0,6,0,8);card.setLayoutParams(cp);card.setRadius(dp(18));card.setCardElevation(dp(1));card.setStrokeWidth(dp(1));card.setStrokeColor(androidx.core.content.ContextCompat.getColor(c,R.color.border_subtle));card.setCardBackgroundColor(androidx.core.content.ContextCompat.getColor(c,R.color.bg_card));LinearLayout root=new LinearLayout(c);root.setOrientation(1);root.setPadding(dp(14),dp(12),dp(14),dp(12));card.addView(root);LinearLayout header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);TextView cat=new TextView(c);cat.setTextSize(12);cat.setTextColor(ThemePaletteManager.resolvePrimaryColor(c));cat.setTypeface(null,1);header.addView(cat,new LinearLayout.LayoutParams(0,-2,1));TextView date=new TextView(c);date.setTextSize(10);date.setTextColor(androidx.core.content.ContextCompat.getColor(c,R.color.text_secondary));header.addView(date);root.addView(header);TextView preview=new TextView(c);preview.setTextSize(14);preview.setTextColor(androidx.core.content.ContextCompat.getColor(c,R.color.text_primary));preview.setMaxLines(2);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,-2);pp.topMargin=dp(7);root.addView(preview,pp);TextView body=new TextView(c);body.setTextSize(14);body.setTextColor(androidx.core.content.ContextCompat.getColor(c,R.color.text_primary));body.setVisibility(View.GONE);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(8);root.addView(body,bp);MaterialButton like=new MaterialButton(c);like.setText("Like");like.setVisibility(View.GONE);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(40));lp.topMargin=dp(8);root.addView(like,lp);return new Holder(card,cat,date,preview,body,like);}
 public void onBindViewHolder(@NonNull Holder h,int position){MessageManager.MessageItem x=items.get(position);h.category.setText(x.category);h.date.setText(format(x.date));h.preview.setText(x.content);h.body.setText(x.content);h.body.setVisibility(View.GONE);h.like.setVisibility(View.GONE);h.like.setText(x.liked?"Liked ✓":"Like");h.like.setEnabled(!x.liked);h.itemView.setOnClickListener(v->{boolean show=h.body.getVisibility()!=View.VISIBLE;h.body.setVisibility(show?View.VISIBLE:View.GONE);h.preview.setVisibility(show?View.GONE:View.VISIBLE);h.like.setVisibility(show&&x.senderId!=null&&!x.senderId.isEmpty()?View.VISIBLE:View.GONE);});h.like.setOnClickListener(v->{h.like.setEnabled(false);MessageManager.likeMessage(x.id,x.senderId,x.category,x.content,token,(ok,msg)->{if(ok){x.liked=true;h.like.setText("Liked ✓");h.like.setEnabled(false);}else h.like.setEnabled(true);Toast.makeText(c,msg,Toast.LENGTH_SHORT).show();});});}
 public int getItemCount(){return items.size();}private int dp(float n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);}private String format(String s){try{return new SimpleDateFormat("MMM d · h:mm a",Locale.getDefault()).format(new Date(Long.parseLong(s)));}catch(Exception e){return s;}}
 static class Holder extends RecyclerView.ViewHolder{TextView category,date,preview,body;MaterialButton like;Holder(View v,TextView c,TextView d,TextView p,TextView b,MaterialButton l){super(v);category=c;date=d;preview=p;body=b;like=l;}}
}
